            "output/debug_logs.json", IssueSeverity.Error,
            "Отсутствует обязательная секция 'Охват NPC-анализа' / 'NPC Scope' в gm_thoughts_markdown",
            code: "missing_npc_scope",
            section: "npc_scope",
