            actual: "missing",
            repairHint: "Добавь секцию '## Охват NPC-анализа' с режимом, релевантными акторами и обоснованием."));
        return issues;
    }

    var scopeMode = ParseReasoningScopeMode(scope.Mode);
    if (!scope.HasModeField || scopeMode == ReasoningScopeMode.Unknown)
    {
