            code: !scope.HasModeField || string.IsNullOrWhiteSpace(scope.Mode) ? "missing_scope_mode" : "invalid_scope_mode",
            section: "npc_scope",
            expected: "Mode = Scene-local, World-progression, Guardian-centric or Mixed",
